{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "A CF3-substituted pyridine-containing PET tracer showed high brain uptake and fast kinetics in rodents and non-human primates, supporting CNS access for the query's CF3-pyridine heteroaromatic core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "A morpholine-containing heteroaromatic compound showed excellent in vivo brain penetration (Kp 11.4) with negligible P-gp efflux, directly supporting the morpholine-substituted heteroaromatic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "A morpholine-containing lipophilic compound rapidly distributed to brain with brain concentrations exceeding plasma at Tmax, supporting adequate CNS access for morpholine-bearing compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "A CF3-heteroaryl compound, even with a carboxylic acid, crossed the BBB in rat PET imaging, indicating that the CF3-heteroaryl motif does not preclude brain entry; the query is more lipophilic.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A CF3-containing heteroaromatic PET ligand accumulated in brain regions in rats, supporting brain penetration of CF3-heteroaromatic compounds similar to the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple structurally related CF3-heteroaryl and morpholine-containing compounds demonstrate adequate CNS penetration, with no contradictory evidence; the query is predicted to have meaningful CNS access.",
  "evidence_gaps": [
    "No direct brain, CSF, or plasma measurement for the exact query molecule.",
    "Efflux liability of the query was not directly assessed, though a close morpholine-containing analog showed negligible P-gp efflux.",
    "Human CNS penetration data are absent for the exact query structure."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

